import asyncio, random, ast, sys
sys.path.insert(0, ".")
from inventory import Inventory
from payments import PaymentGateway
from checkout import checkout

INITIAL_STOCK = 5; UNIT_PRICE = 100.0; ORDER_COUNT = 12; TRIALS = 6

async def run_one(seed):
    random.seed(seed)
    inventory = Inventory(INITIAL_STOCK)
    gateway = PaymentGateway(failure_rate=0.25)
    orders = [checkout(f"order_{i}", 1, UNIT_PRICE, inventory, gateway) for i in range(ORDER_COUNT)]
    results = await asyncio.gather(*orders)
    successful = sum(results)
    charge_ids = [c["order_id"] for c in gateway.charges]
    duplicates = len(charge_ids) - len(set(charge_ids))
    return {"stock": inventory.stock, "charged": gateway.total_charged,
            "successful": successful, "duplicates": duplicates,
            "expected_charge": successful * UNIT_PRICE,
            "expected_stock": INITIAL_STOCK - successful}

CONCURRENCY_PRIMITIVES = {"Lock", "RLock", "Semaphore", "BoundedSemaphore", "Event", "Condition"}
def instantiates(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return False
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if isinstance(func, ast.Attribute) and func.attr in CONCURRENCY_PRIMITIVES:
            return True
        if isinstance(func, ast.Name) and func.id in CONCURRENCY_PRIMITIVES:
            return True
    return False

all_ok = True
for t in range(TRIALS):
    r = asyncio.run(run_one(t * 7))
    errors = []
    if r["stock"] < 0: errors.append(f"negative stock ({r['stock']})")
    elif r["stock"] != r["expected_stock"]: errors.append(f"stock mismatch (stock={r['stock']}, expected={r['expected_stock']})")
    if abs(r["charged"] - r["expected_charge"]) > 0.01: errors.append(f"charge mismatch (charged={r['charged']}, expected={r['expected_charge']})")
    if r["duplicates"] > 0: errors.append(f"{r['duplicates']} duplicate charge(s)")
    ok = not errors
    all_ok = all_ok and ok
    print(f"trial {t+1}: {'PASS' if ok else 'FAIL: ' + ', '.join(errors)}  (stock={r['stock']}, successful={r['successful']}, charged=${r['charged']:.2f}, dupes={r['duplicates']})")

has_lock = instantiates(open("inventory.py").read()) or instantiates(open("checkout.py").read())
print(f"locking_mechanism: {'PASS' if has_lock else 'FAIL'}")
print("ALL 6 TRIALS PASS" if all_ok else "SOME TRIALS FAILED")
EOF
